    example={'schema_version':'cal-evidence-set-record/v1','artifact_type_ref':'cal.artifact-type.evidence-set/v1','set_id':'EXAMPLE-RESIDUE-CHECKER-EVIDENCE-001','status':'candidate-unadmitted','authority_effect':'none','owner_route':'route:evidence-owner','scope_ref':'scope:residue-checker-review','profile':'candidate:question-evidence-inventory/v1','questions':[{'question_id':'local-checks','question':'Does the candidate report passing its documented local validation?'},{'question_id':'general-proof','question':'Does local validation establish general semantic preservation?'}],'members':[{'member_id':'validation','binding':binding(PREVIOUS/'receipts/validation.json'),'contributions':[{'question_ref':'local-checks','role':'supporting','rationale':'The bound local validation record reports PASS.'}]},{'member_id':'limitations','binding':binding(PREVIOUS/'README.md'),'contributions':[{'question_ref':'general-proof','role':'counterevidence','rationale':'The documented limits explicitly exclude semantic equivalence and actual operation provenance.'}]}],'gaps':[{'question_ref':'general-proof','missing':'Independent semantic preservation evidence.','owner_route':'route:representation-owner','next_step':'Define a semantic preservation test and obtain attributable run evidence before making a broader claim.'}],'challenge_route':'route:evidence-review-challenge','source_direction':{'canonical':'evidence-set-record.json','human_projection':'EVIDENCE-SET.md','projection_policy':'generated-only'},'claim_ceiling':'Exact evidence inventory and declared question coverage only; role assignments, truth, sufficiency and conclusions remain unproven.'}
